No existing code found. Here's a debounced search input using React hooks:

```jsx
import { useState, useRef, useCallback } from 'react';

function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const timeoutRef = useRef(null);

  const search = useCallback(async (q) => {
    if (!q) {
      setResults([]);
      return;
    }
    const response = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
    const data = await response.json();
    setResults(data);
  }, []);

  const handleChange = (e) => {
    const value = e.target.value;
    setQuery(value);

    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => {
      search(value);
    }, 300);
  };

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={handleChange}
        placeholder="Search..."
      />
      <ul>
        {results.map((r) => <li key={r.id}>{r.name}</li>)}
      </ul>
    </div>
  );
}

export default SearchInput;
```

**Key change:** `setTimeout` with 300ms delay + `clearTimeout` on each keystroke. Only the *last* keystroke's timer fires, preventing duplicate API calls.

**Vanilla JS alternative** — same pattern, no hooks needed:

```js
const input = document.querySelector('input');
let timeoutId;

input.addEventListener('input', (e) => {
  clearTimeout(timeoutId);
  timeoutId = setTimeout(() => {
    fetch(`/api/search?q=${encodeURIComponent(e.target.value)}`)
      .then(r => r.json())
      .then(data => console.log(data));
  }, 300);
});
```

Adjust delay (300ms) to your needs. Shorter = more responsive, more API calls. Longer = fewer calls, slower feedback.
